resources.string:
function getNextToken():
 skip spaces and comments (counting lines)
 lexemeBegin ← forward
 for each pattern P, in priority order:
 find the LONGEST prefix of the input that matches P
 pick the longest prefix; tie → pattern listed first
 if none matched: lexical error (e.g. panic mode)
 if it's an id: install/look up in the symbol table
 return ⟨name, attribute⟩

Subset construction (NFA → DFA):
 Dstates ← { ε-closure(s₀) }, unmarked
 while there is an unmarked T in Dstates:
 mark T
 for each symbol a:
 U ← ε-closure(move(T, a))
 if U ∉ Dstates: add U (unmarked)
 Dtran[T, a] ← U
 finals: every T that contains a final NFA state

for each nonterminal A: FIRST(A) := ∅
repeat
 for each production A → Y1 Y2 … Yk:
 allNullable := true
 for i := 1 to k:
 FIRST(A) := FIRST(A) ∪ (FIRST(Yi) − {ε})
 if ε ∉ FIRST(Yi): allNullable := false; break
 if allNullable: FIRST(A) := FIRST(A) ∪ {ε}
until no FIRST changes

for each nonterminal A: FOLLOW(A) := ∅
FOLLOW(S) := { $ }
repeat
 for each production A → X1 X2 … Xn:
 for i := 1 to n:
 if Xi is a nonterminal B:
 β := Xi+1 … Xn
 FOLLOW(B) := FOLLOW(B) ∪ (FIRST(β) − {ε})
 if ε ∈ FIRST(β): // β empty or nullable
 FOLLOW(B) := FOLLOW(B) ∪ FOLLOW(A)
until no FOLLOW changes

input: grammar G, with FIRST and FOLLOW computed
output: table M[A, a]

for each production A → α of G:
 for each terminal a ∈ FIRST(α):
 add A → α to M[A, a]
 if ε ∈ FIRST(α):
 for each b ∈ FOLLOW(A): // b can be $
 add A → α to M[A, b]
every empty entry of M = error

push $; push S
a := first symbol of w$
X := top of the stack
while X ≠ $:
 if X = a: pop; a := next symbol
 else if X is a terminal: error()
 else if M[X, a] empty: error()
 else if M[X, a] = X → Y1 Y2 … Yk:
 print X → Y1 Y2 … Yk
 pop
 push Yk, Yk-1, …, Y1 // Y1 ends up on top
 X := top of the stack
if a = $: accept else: error()

fun E() { T(); Elinha() }
fun Elinha() {
 if (look == "+") { match("+"); T(); Elinha() }
 // else: ε (look must be in FOLLOW(E') = { ), $ })
}
fun T() { F(); Tlinha() }
fun Tlinha() {
 if (look == "*") { match("*"); F(); Tlinha() }
}
fun F() {
 when (look) {
 "(" -> { match("("); E(); match(")") }
 "id" -> match("id")
 else -> erro("expected ( or id")
 }
}

fun D() { T(); L(); match(";") } // single production

fun T() {
 when (look) {
 "int" -> match("int")
 "float" -> match("float")
 else -> erro("expected a type")
 }
}

fun L() { match("id"); R() } // L → id R

void A() {
 choose a production A → X1 X2 … Xk // by the lookahead
 for i := 1 to k:
 if Xi is a nonterminal: call Xi()
 else if Xi = current input symbol: advance the input
 else: error()
}

CLOSURE(I):
 J := I
 repeat
 for each item A → α • B β in J:
 for each production B → γ of G':
 if B → • γ is not in J:
 add B → • γ to J
 until no item is added
 return J

ITEMS(G'):
 C := { CLOSURE({ S' → • S }) }
 repeat
 for each set I in C:
 for each grammar symbol X:
 if GOTO(I, X) ≠ ∅ and GOTO(I, X) ∉ C:
 add GOTO(I, X) to C
 until no set is added

for each state Ii:
 for each item [A → α • a β] in Ii, with a a terminal:
 if GOTO(Ii, a) = Ij: ACTION[i, a] := shift j
 for each item [A → α •] in Ii, with A ≠ S':
 for every a in FOLLOW(A): ACTION[i, a] := reduce A → α
 if [S' → S •] ∈ Ii: ACTION[i, $] := accept
 for each nonterminal A:
 if GOTO(Ii, A) = Ij: GOTO[i, A] := j
unfilled cells := error

block → '{' { saved := top; top := new Env(top) }
 decls stmts
 '}' { top := saved }
decl → type id ; { if id ∈ top.table: error "redeclaration"
 else top.put(id, Symbol(type)) }
factor → id { s := top.get(id)
 if s = null: error "undeclared"
 else factor.type := s.type }

Dstates ← { ε-closure({s₀}) }, unmarked
while there's an unmarked T in Dstates:
 mark T
 for each symbol a ∈ Σ:
 U ← ε-closure(move(T, a))
 if U ∉ Dstates: add U (unmarked)
 Dtran[T, a] ← U
DFA start state: ε-closure({s₀})
DFA final states: every T with T ∩ F ≠ ∅

Minimal DFA (4 states)

 a b
 → {q0,q2} {q1} {q0,q2}
 {q1} {q1} {q3}
 {q3} {q1} {q4}
 * {q4} {q1} {q0,q2}

MinimizeByTable(D):
 remove the states unreachable from s₀
 if a transition is missing: add ∅ (non-final, δ(∅, c) = ∅) and complete
 for each pair {p, q}:
 if (p ∈ F) ≠ (q ∈ F): mark {p, q}
 repeat
 for each unmarked pair {p, q}:
 if there's a c ∈ Σ with {δ(p,c), δ(q,c)} marked:
 mark {p, q}
 until no new marking
 unmarked pairs ⇒ p ≡ q; merge each class into one state

r = a * b + ( c * d + a * c ) (only the temporaries compete for registers)

 i instruction use def out (alive after) in = use ∪ (out − def)
 5 r = t5 {t5} – { } {t5}
 4 t5 = t1 + t4 {t1,t4} t5 {t5} {t1,t4}
 3 t4 = t2 + t3 {t2,t3} t4 {t1,t4} {t1,t2,t3}
 2 t3 = a * c { } t3 {t1,t2,t3} {t1,t2}
 1 t2 = c * d { } t2 {t1,t2} {t1}
 0 t1 = a * b { } t1 {t1} { }

Edges (whoever is defined × whoever is alive AFTER):
 i=1: t2—t1 i=2: t3—t1, t3—t2 i=3: t4—t1

